//! Golden-corpus STALENESS pin — the mechanical tie between the committed
//! fixture corpus (`tests/goldens/*.json`) and the two Python LAW files it
//! was generated from (DEC-RUST-CALENDAR-LEAVES-001 staleness law; the T18
//! independent-audit fold).
//!
//! The goldens are generated by `tests/goldens/generate_goldens.py` running
//! the REAL Python laws — so a Python-law edit that ships WITHOUT a corpus
//! regeneration would leave the crate byte-parity-"green" against a STALE
//! oracle. This pin makes that drift LOUD: the two law files are hashed
//! under the SAME digest scheme as the crate's source-digest machinery
//! (FRAMING v1 of `rust/source_digest_core.rs`, re-included below — reuse,
//! not a copy; `single_file_frame_matches_shared_framing_core` proves the
//! one-file wrapper can never drift from the shared core) and asserted
//! against digests pinned from the exact files the committed corpus was
//! generated from.
//!
//! On a legitimate law change: regenerate the corpus, verify parity, then
//! re-pin (the assert message carries the recipe). In an out-of-repo build
//! (a future crates-only checkout — no `brutex/` tree beside the crate) the
//! pin SKIPS loudly: absence must not fail, staleness must.

include!("../../source_digest_core.rs");

/// The two Python LAW files the golden corpus is generated from, with their
/// pinned FRAMING v1 single-file digests (rel path is the frame path).
///
/// RE-PIN RECIPE (after a deliberate law change):
///   .venv/bin/python rust/brutex-calendar/tests/goldens/generate_goldens.py
///   → review the fixture diff → cargo test → paste the new hex the failing
///   assert prints (or recompute: blake3 over
///   `rel ‖ 0x00 ‖ u64-le(len) ‖ bytes`).
const PINNED_LAW_DIGESTS: &[(&str, &str)] = &[
    (
        "brutex/calendars/settle_evidence.py",
        "37e5d11e1b5c33eff1556f9e4dce57d81518ab76a22a0d66213d8322d57d5751",
    ),
    (
        "brutex/calendars/observed_sessions.py",
        "123f9b9aa263c947b5dd4062162e89e8a37bfd4b7a217c44a5537830f2a2b9c1",
    ),
];

/// FRAMING v1 applied to ONE file: the shared core's per-file frame
/// (`path-bytes ‖ 0x00 ‖ u64-le(content length) ‖ raw content`) hashed with
/// BLAKE3 — for a single-file digest set this equals `crate_source_digest`
/// (proven by `single_file_frame_matches_shared_framing_core`).
fn law_file_digest(rel: &str, contents: &[u8]) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(rel.as_bytes());
    hasher.update(&[0u8]);
    hasher.update(&(contents.len() as u64).to_le_bytes());
    hasher.update(contents);
    hasher.finalize().to_hex().to_string()
}

fn repo_root() -> std::path::PathBuf {
    // CARGO_MANIFEST_DIR = <repo>/rust/brutex-calendar → two levels up.
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

#[test]
fn single_file_frame_matches_shared_framing_core() {
    // Mechanical reuse proof: build a one-file digest set (no Cargo.toml,
    // one src/*.rs) and assert the local wrapper equals the shared core's
    // `crate_source_digest` — so `law_file_digest` can never drift from
    // FRAMING v1 silently.
    let root = std::path::Path::new(env!("CARGO_TARGET_TMPDIR")).join("law_digest_frame_check");
    let src = root.join("src");
    std::fs::create_dir_all(&src)
        .unwrap_or_else(|err| panic!("cannot create {}: {err}", src.display()));
    let contents = b"// FRAMING v1 one-file consistency check\n";
    std::fs::write(src.join("x.rs"), contents)
        .unwrap_or_else(|err| panic!("cannot write frame-check fixture: {err}"));
    assert_eq!(
        crate_source_digest(&root),
        law_file_digest("src/x.rs", contents),
        "law_file_digest drifted from the shared FRAMING v1 core"
    );
}

#[test]
fn python_law_files_match_pinned_digests() {
    let repo = repo_root();
    for (rel, pinned) in PINNED_LAW_DIGESTS {
        let path = repo.join(rel);
        if !path.is_file() {
            // Out-of-repo build (crates-only checkout): the law files are not
            // beside the crate — absence must not fail, staleness must.
            eprintln!(
                "law_digest_pin: {rel} not found beside the crate (out-of-repo build) — \
                 SKIPPING the staleness pin for this file"
            );
            continue;
        }
        let contents = std::fs::read(&path)
            .unwrap_or_else(|err| panic!("law_digest_pin: cannot read {}: {err}", path.display()));
        assert_eq!(
            law_file_digest(rel, &contents),
            *pinned,
            "{rel} changed — regenerate the golden corpus \
             (tests/goldens/generate_goldens.py) with the updated laws, verify parity, \
             then re-pin this digest (DEC-RUST-CALENDAR-LEAVES-001 staleness law)"
        );
    }
}
